      pt: ["Construído em 1894 como mercado de peixe.", "Planta octogonal de 8 lados.", "Estrutura de ferro fundido do século XIX.", "Mais de 100 bancas de comida.", "Originalmente situado na costa (posteriormente aterrado).", "Restaurado em 2014."],
      fr: ["Construit en 1894 comme marché aux poissons.", "Plan octogonal à 8 côtés.", "Structure en fonte du XIXe siècle.", "Plus de 100 étals de nourriture.", "Initialement situé sur la côte (plus tard remblayé).", "Restauré en 2014."],
