      hu: ["1827-ben épült.", "1992-ben nemzeti emlékművé nyilvánították.", "Előtte egy bronz elefántszobor áll, Chulalongkorn sziámi király ajándéka."],
      ro: ["Construită în 1827.", "A fost declarată monument național în 1992.", "O statuie de bronz a unui elefant, un cadou de la regele Chulalongkorn al Siamului, stă în față."],
      en: ["Built in 1827.", "It was gazetted as a National Monument in 1992.", "A bronze elephant statue, a gift from King Chulalongkorn of Siam, stands in front."],
